bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,pid='sp_76f23430d1c29ca355960a95';
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,
 password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:6000});
try{
 const t=await db.query('SELECT p.status AS product_status,p.price_stars,p.title,t.status AS post_status,t.telegram_message_id,t.chat_id,t.message_thread_id,t.display_text FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON p.product_id=t.product_id WHERE p.product_id=$1',[pid]);
 if(t.rowCount!==1)throw Error('STK_PAID_EXISTING_PRODUCT_RECEIPT_ABSENT');
 const r=t.rows[0];
 console.log('STK_PAID_PRODUCT_STATUS='+r.product_status);
 console.log('STK_PAID_TOPIC_STATUS='+r.post_status);
 console.log('STK_PAID_STARS='+r.price_stars);
 console.log('STK_PAID_MESSAGE_ID='+r.telegram_message_id);
 console.log('STK_PAID_THREAD_ID='+r.message_thread_id);
 console.log('STK_PAID_TITLE_ONLY='+(r.display_text==='🎨 '+r.title?'YES':'NO'));
 const sales=await db.query('SELECT COUNT(*)::int AS n FROM videobot_sticker_paid_photo_sales WHERE product_id=$1',[pid]);
 console.log('STK_PAID_COMPLETED_RECEIPTS='+sales.rows[0].n);
 const orders=await db.query('SELECT invoice_state,COUNT(*)::int AS n FROM videobot_sticker_orders WHERE product_id=$1 GROUP BY invoice_state ORDER BY invoice_state',[pid]);
 console.log('STK_PAID_INVOICE_STATES='+orders.rows.map(x=>x.invoice_state+':'+x.n).join(','));
 const current=await db.query("SELECT current_database() AS n, (SELECT MAX(version) FROM videobot_sticker_products WHERE product_id=$1)::int AS version",[pid]);
 console.log('STK_PAID_PRODUCT_VERSION='+current.rows[0].version);
}finally{await db.end();}
NODE
echo STK_PAID_EXISTING_POST_SALES_PRECHECK=PASS
